package json

import (
	"encoding/json"
)

// StdlibSerializer implements ports.Serializer using
// Go's standard encoding/json. Used as fallback when there is no
// code generated by nitro/codegen/json.
type StdlibSerializer struct{}

// NewStdlibSerializer creates a new StdlibSerializer.
func NewStdlibSerializer() *StdlibSerializer {
	return &StdlibSerializer{}
}

// MarshalJSON serializes v to JSON using encoding/json.
func (s *StdlibSerializer) MarshalJSON(v any) ([]byte, error) {
	return json.Marshal(v)
}

// UnmarshalJSON deserializes JSON into v using encoding/json.
func (s *StdlibSerializer) UnmarshalJSON(data []byte, v any) error {
	return json.Unmarshal(data, v)
}
